CREATE TABLE IF NOT EXISTS email_tags(email_id INTEGER NOT NULL,tag_id INTEGER NOT NULL,PRIMARY KEY(email_id,tag_id),FOREIGN KEY(email_id)REFERENCES emails(id)ON DELETE CASCADE,FOREIGN KEY(tag_id)REFERENCES tags(id)ON DELETE CASCADE);
CREATE VIRTUAL TABLE IF NOT EXISTS emails_fts USING fts5(email_id UNINDEXED,alias_address,sender,sender_name,subject,text_body,content='emails',content_rowid='id');
CREATE TRIGGER IF NOT EXISTS emails_fts_insert AFTER INSERT ON emails BEGIN INSERT INTO emails_fts(rowid,email_id,alias_address,sender,sender_name,subject,text_body)VALUES(new.id,new.id,new.alias_address,new.sender,new.sender_name,new.subject,new.text_body);END;
CREATE TRIGGER IF NOT EXISTS emails_fts_delete BEFORE DELETE ON emails BEGIN INSERT INTO emails_fts(emails_fts,rowid,email_id,alias_address,sender,sender_name,subject,text_body)VALUES('delete',old.id,old.id,old.alias_address,old.sender,old.sender_name,old.subject,old.text_body);END;
CREATE TRIGGER IF NOT EXISTS emails_fts_update AFTER UPDATE ON emails BEGIN INSERT INTO emails_fts(emails_fts,rowid,email_id,alias_address,sender,sender_name,subject,text_body)VALUES('delete',old.id,old.id,old.alias_address,old.sender,old.sender_name,old.subject,old.text_body);INSERT INTO emails_fts(rowid,email_id,alias_address,sender,sender_name,subject,text_body)VALUES(new.id,new.id,new.alias_address,new.sender,new.sender_name,new.subject,new.text_body);END;
